mapper.select:
SELECT search_id, keyword, search_type, searched_at
FROM search_histories
WHERE user_id = #{userId}
ORDER BY searched_at DESC, search_id DESC
LIMIT #{limit}

SELECT user_id
FROM search_histories
WHERE search_id = #{searchId}

mapper.delete:
DELETE FROM search_histories
WHERE search_id = #{searchId}
  AND user_id = #{userId}

mapper.select:
SELECT user_id, nickname, profile_image_url
FROM users
WHERE nickname LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'

    AND user_id < #{cursor}

ORDER BY user_id DESC
LIMIT #{limit}

SELECT
FROM posts p JOIN users u ON u.user_id = p.user_id WHERE p.is_public = TRUE AND MATCH(p.content) AGAINST(#{booleanQuery} IN BOOLEAN MODE)
AND p.post_id < #{cursor}
ORDER BY p.post_id DESC LIMIT #{limit}

SELECT , GROUP_CONCAT(DISTINCT t.tag_name ORDER BY t.tag_name SEPARATOR ',') AS matched_stacks FROM posts p JOIN users u ON u.user_id = p.user_id JOIN post_tags pt ON pt.post_id = p.post_id JOIN tags t ON t.tag_id = pt.tag_id WHERE t.tag_type = 'TECH' AND t.tag_name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\' AND p.is_public = TRUE
AND p.post_id < #{cursor}
GROUP BY p.post_id ORDER BY p.post_id DESC LIMIT #{limit}

mapper.delete:
DELETE FROM search_histories
WHERE user_id = #{userId}
  AND search_id NOT IN (
      SELECT search_id FROM (
          SELECT search_id
          FROM search_histories
          WHERE user_id = #{userId}
          ORDER BY searched_at DESC, search_id DESC
          LIMIT #{keepN}
      ) t
  )
